"use client"

interface Command {
  label: string
  value: string
  icon?: React.ReactNode
  page?: string
  back?: boolean
}

const rootCommands: Command[] = [
  {
    label: "Change Theme...",
    value: "theme",
    icon: <LuPalette />,
    page: "theme",
  },
  { label: "Search Projects...", value: "projects", icon: <LuSearch /> },
]

const themeCommands: Command[] = [
  { label: "Light Theme", value: "light", icon: <LuSun /> },
  { label: "Dark Theme", value: "dark", icon: <LuMoon /> },
  { label: "System Theme", value: "system", icon: <LuMonitor /> },
  { label: "Go Back", value: "back", icon: <LuArrowLeft />, back: true },
]

const filterOptions = { sensitivity: "base" } as const

export const CommandPaletteNested = () => {
  const [query, setQuery] = useState("")
  const [pages, setPages] = useState<string[]>([])
  const [theme, setTheme] = useState("system")

  const page = pages[pages.length - 1]

  const { contains } = useFilter(filterOptions)

  const collection = useMemo(() => {
    const source = page === "theme" ? themeCommands : rootCommands
    return createListCollection({
      items: source.filter((item) => contains(item.label, query)),
    })
  }, [page, query, contains])

  return (
    <CommandPalette.Root
      collection={collection}
      hotkeys={[]}
      onSelect={({ itemValue }) => {
        const item = collection.find(itemValue)
        if (!item) return
        setQuery("")
        if (item.back) {
          setPages((prev) => prev.slice(0, -1))
        } else if (item.page) {
          setPages((prev) => [...prev, item.page!])
        } else if (page === "theme") {
          setTheme(item.value)
          setPages([])
          toaster.create({
            description: `${item.label} enabled`,
            type: "success",
          })
        }
      }}
      onInputValueChange={(e) => setQuery(e.inputValue)}
    >
      <CommandPalette.Trigger asChild>
        <Button variant="outline">
          Open palette <Kbd size="sm">⌘K</Kbd>
        </Button>
      </CommandPalette.Trigger>
      <Portal>
        <CommandPalette.Backdrop />
        <CommandPalette.Positioner>
          <CommandPalette.Panel>
            <CommandPalette.Control>
              <CommandPalette.Indicator />
              {page && <Kbd size="sm">{page}</Kbd>}
              <CommandPalette.Input
                placeholder={page ? "Pick a theme..." : "Type a command..."}
                value={query}
                onKeyDown={(e) => {
                  if (e.key === "Backspace" && !query && pages.length) {
                    e.preventDefault()
                    setPages((prev) => prev.slice(0, -1))
                  }
                }}
              />
            </CommandPalette.Control>
            <CommandPalette.List>
              {collection.items.map((item) => (
                <CommandPalette.Item
                  item={item}
                  key={item.value}
                  closeOnSelect={item.page || item.back ? false : undefined}
                >
                  {item.icon}
                  <CommandPalette.ItemText>
                    {item.label}
                  </CommandPalette.ItemText>
                </CommandPalette.Item>
              ))}
              <CommandPalette.Empty>No results found</CommandPalette.Empty>
            </CommandPalette.List>
            <CommandPalette.Footer>
              <Span>Theme: {theme}</Span>
              <Span ms="auto" display="inline-flex" alignItems="center" gap="1">
                <Kbd>
                  <Icon boxSize="3.5">
                    <LuDelete />
                  </Icon>
                  <VisuallyHidden>Backspace</VisuallyHidden>
                </Kbd>
                to go back
              </Span>
            </CommandPalette.Footer>
          </CommandPalette.Panel>
        </CommandPalette.Positioner>
      </Portal>
    </CommandPalette.Root>
  )
}

"use client"
export const CommandPaletteVirtualized = () => {
  const scrollRef = useRef<HTMLDivElement>(null)

  const { contains } = useFilter({ sensitivity: "base" })

  const { collection, filter } = useListCollection({
    initialItems: commands,
    filter: contains,
  })

  const virtualizer = useVirtualizer({
    count: collection.size,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 32,
    overscan: 10,
  })

  return (
    <CommandPalette.Root
      collection={collection}
      scrollToIndexFn={(details) => {
        virtualizer.scrollToIndex(details.index, { align: "auto" })
      }}
      onInputValueChange={(e) => filter(e.inputValue)}
    >
      <CommandPalette.Trigger asChild>
        <Button variant="outline">
          Open palette <Kbd size="sm">⌘K</Kbd>
        </Button>
      </CommandPalette.Trigger>
      <Portal>
        <CommandPalette.Backdrop />
        <CommandPalette.Positioner>
          <CommandPalette.Panel>
            <CommandPalette.Control>
              <CommandPalette.Indicator />
              <CommandPalette.Input
                placeholder={`Search ${commands.length.toLocaleString()} commands...`}
              />
            </CommandPalette.Control>
            <CommandPalette.List ref={scrollRef}>
              <div
                style={{
                  height: `${virtualizer.getTotalSize()}px`,
                  width: "100%",
                  position: "relative",
                }}
              >
                {virtualizer.getVirtualItems().map((virtualItem) => {
                  const item = collection.items[virtualItem.index]
                  return (
                    <CommandPalette.Item
                      key={item.value}
                      item={item}
                      aria-posinset={virtualItem.index + 1}
                      aria-setsize={collection.size}
                      style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        width: "100%",
                        height: `${virtualItem.size}px`,
                        transform: `translateY(${virtualItem.start}px)`,
                      }}
                    >
                      <CommandPalette.ItemText>
                        {item.label}
                      </CommandPalette.ItemText>
                    </CommandPalette.Item>
                  )
                })}
              </div>
              <CommandPalette.Empty>No commands found</CommandPalette.Empty>
            </CommandPalette.List>
            <CommandPalette.Footer>
              {collection.size.toLocaleString()} commands
            </CommandPalette.Footer>
          </CommandPalette.Panel>
        </CommandPalette.Positioner>
      </Portal>
    </CommandPalette.Root>
  )
}

